331→func (c *ClaudeCodeAgent) CalculateTotalTokenUsage(transcriptData []byte, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
332→	if len(transcriptData) == 0 {
333→		return &agent.TokenUsage{}, nil
334→	}
335→
336→	// Slice to the relevant portion and parse
337→	sliced := transcript.SliceFromLine(transcriptData, startLine)
338→	parsed, err := transcript.ParseFromBytes(sliced)
339→	if err != nil {
340→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
341→	}
342→
343→	// Calculate token usage from parsed transcript
344→	mainUsage := CalculateTokenUsage(parsed)
345→
346→	// Extract spawned agent IDs from the same parsed transcript
347→	agentIDs := ExtractSpawnedAgentIDs(parsed)
348→
349→	// Calculate subagent token usage (skip when subagentsDir is empty to avoid reading from cwd)
350→	if len(agentIDs) > 0 && subagentsDir != "" {
351→		subagentUsage := &agent.TokenUsage{}
352→		for agentID := range agentIDs {
353→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
354→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
355→			if err != nil {
356→				// Agent transcript may not exist yet or may have been cleaned up
357→				continue
358→			}
359→			subagentUsage.InputTokens += agentUsage.InputTokens
360→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
361→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
362→			subagentUsage.OutputTokens += agentUsage.OutputTokens
363→			subagentUsage.APICallCount += agentUsage.APICallCount
364→		}
365→		if subagentUsage.APICallCount > 0 {
366→			mainUsage.SubagentTokens = subagentUsage
367→		}
368→	}
369→
370→	return mainUsage, nil
371→}
