375→// startLine, collects modified files from the main agent, then reads each
376→// subagent's transcript from subagentsDir to collect their modified files too.
377→// The result is a deduplicated list of all modified file paths.
378→func (c *ClaudeCodeAgent) ExtractAllModifiedFiles(transcriptData []byte, startLine int, subagentsDir string) ([]string, error) {
379→	if len(transcriptData) == 0 {
380→		return nil, nil
