388→	}
389→
390→	// Collect modified files from main agent
391→	fileSet := make(map[string]bool)
392→	var files []string
393→	for _, f := range ExtractModifiedFiles(parsed) {
394→		if !fileSet[f] {
395→			fileSet[f] = true
396→			files = append(files, f)
397→		}
398→	}
399→
400→	// Find spawned subagents and collect their modified files (skip when subagentsDir is empty to avoid reading from cwd)
401→	agentIDs := ExtractSpawnedAgentIDs(parsed)
402→	if subagentsDir == "" {
403→		return files, nil
404→	}
405→	for agentID := range agentIDs {
406→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
