```go
// extractSubagentBlobs walks the shadow branch tree under .entire/metadata/<session-id>/tasks/
// and returns agent transcript blobs remapped to subagents/ paths for the committed tree.
// Only agent-*.jsonl files are included (checkpoint.json and incremental checkpoints are excluded).
func extractSubagentBlobs(repo *git.Repository, shadowRef plumbing.Hash, sessionID string) (map[string]object.TreeEntry, error) {
	commit, err := repo.CommitObject(shadowRef)
	if err != nil {
		return nil, fmt.Errorf("failed to get shadow commit: %w", err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get shadow tree: %w", err)
	}

	tasksPrefix := paths.SessionMetadataDirFromSessionID(sessionID) + "/tasks/"
	blobs := make(map[string]object.TreeEntry)

	// Walk the tree looking for agent-*.jsonl files under tasks/
	err = tree.Files().ForEach(func(f *object.File) error {
		if !strings.HasPrefix(f.Name, tasksPrefix) {
			return nil
		}
		relPath := strings.TrimPrefix(f.Name, tasksPrefix)
		// Only include agent-*.jsonl files
		base := filepath.Base(relPath)
		if !strings.HasPrefix(base, "agent-") || !strings.HasSuffix(base, ".jsonl") {
			return nil
		}
		// Remap: tasks/<tool-use-id>/agent-<id>.jsonl -> subagents/<tool-use-id>/agent-<id>.jsonl
		dir := filepath.Dir(relPath) // <tool-use-id>
		committedPath := "subagents/" + dir + "/" + base
		blobs[committedPath] = object.TreeEntry{
			Name: committedPath,
			Mode: f.Mode,
			Hash: f.Hash,
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to walk shadow tree: %w", err)
	}

	return blobs, nil
}
```

